function flattenValues(obj) {
  const result = [];
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    if (typeof obj[key] === "object" && obj[key] !== null && !Array.isArray(obj[key])) {
      result.push(...flattenValues(obj[key]));
    } else {
      result.push(obj[key]);
    }
  }
  return result;
}
